BEGIN;
CREATE TABLE IF NOT EXISTS t_user (
    id_user integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    u_username varchar(255),
    u_delete varchar(255)
);
ALTER TABLE t_settings ADD COLUMN IF NOT EXISTS id_user integer;
ALTER TABLE t_income ADD COLUMN IF NOT EXISTS id_sale integer;
ALTER TABLE t_sale ADD COLUMN IF NOT EXISTS id_type integer;
ALTER TABLE t_sale ADD COLUMN IF NOT EXISTS id_art integer;
TRUNCATE TABLE t_group, t_artist, t_type, t_website, t_version, t_product_status, t_product, t_cover, t_product_web, t_type_cost, t_cost, t_cost_detail, t_type_income, t_income, t_lot, t_lot_detail, t_menu, t_payment_method, t_payment_type, t_order, t_order_status, t_order_detail, t_sale, t_settings, t_log_version, t_user RESTART IDENTITY CASCADE;

